import { shuffle } from '@/config'
import { originToUsable, TUnPost } from '@/data/posts'
import { TPost } from '@/types'

export function getLastFetchTime(key: string): number | null {
  try {
    const val = localStorage.getItem(key)
    if (!val) return null
    const ts = Number(val)
    return Number.isFinite(ts) ? ts : null
  } catch {
    return null
  }
}

export function setLastFetchTime(key: string): void {
  try {
    localStorage.setItem(key, String(Date.now()))
  } catch {}
}

export function getLsKey(
  PREFIX: string,
  lang: string,
  page?: string,
  rand?: boolean,
): string {
  return `${PREFIX}${lang}_${page ?? '1'}_${!!rand}`
}

export function transformResponse(
  unformatedPosts: TUnPost[],
  rand?: boolean,
): TPost[] {
  const posts: TPost[] = unformatedPosts.map((post) => originToUsable(post))
  return rand ? shuffle(posts) : posts
}

export function transformResponseWithLimit(
  unformatedPosts: TUnPost[],
  options?: {
    number?: number
    rand?: boolean
  },
): TPost[] {
  const { number, rand } = options ?? {}

  const sliced =
    number !== undefined ? unformatedPosts.slice(0, number) : unformatedPosts

  const mapped = sliced.map((post) => originToUsable(post))

  return rand ? shuffle(mapped) : mapped
}
