import { TUnPost } from '@/data/posts'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useEffect, useState } from 'react'
import {
  getLastFetchTime,
  getLsKey,
  setLastFetchTime,
  transformResponseWithLimit,
} from './utils'

const api = import.meta.env.VITE_API_NEWS

const LS_PREFIX = 'tr'
const STALE_THRESHOLD_MS = 10 * 60 * 1000 // 10 minutes

export const useGetTrending = (
  time?: '1h' | '24h' | '6h' | '7j' | '30j',
  cat?: string,
  rand?: boolean,
  number?: number,
  bgRefresh?: boolean,
) => {
  const queryClient = useQueryClient()
  const [isBackgroundRefreshing, setIsBackgroundRefreshing] = useState(false)
  const queryKey = ['trend', { time, cat, rand: !!rand, number }]
  const query = useQuery({
    enabled: !!time,
    staleTime: 1000 * 600,
    queryKey,
    queryFn: async () => {
      const response = await fetch(`${api}/trending/${time}?cat=${cat}`)

      if (!response.ok) {
        throw new Error('faild to fetch posts')
      }
      const { results: unformatedPosts }: trendingResponse =
        await response.json()

      const posts = transformResponseWithLimit(unformatedPosts, {
        number,
        rand,
      })

      return { posts }
    },
  })

  useEffect(() => {
    if (!bgRefresh || !query.isSuccess || query.isFetching) return

    const lsKey = getLsKey(LS_PREFIX, time!, cat, rand)
    const lastFetch = getLastFetchTime(lsKey)

    if (lastFetch === null) {
      setLastFetchTime(lsKey)
      return
    }
    if (Date.now() - lastFetch < STALE_THRESHOLD_MS) return

    // Stamp immediately to prevent duplicate fetches across re-renders
    setLastFetchTime(lsKey)

    const controller = new AbortController()
    setIsBackgroundRefreshing(true)

    fetch(`${api}/trending/${time}?cat=${cat}&_cb=${Date.now()}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) throw new Error('bg refresh failed')
        return res.json()
      })
      .then(({ results: unformatedPosts }: trendingResponse) => {
        const posts = transformResponseWithLimit(unformatedPosts, {
          number,
          rand,
        })
        if (posts.length > 0) {
          queryClient.setQueryData(queryKey, { posts })
        }
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Background refresh failed', err)
        }
      })
      .finally(() => setIsBackgroundRefreshing(false))

    return () => controller.abort()
  }, [
    bgRefresh,
    query.isSuccess,
    query.isFetching,
    time,
    cat,
    rand,
    number,
    queryClient,
  ])

  return { ...query, isBackgroundRefreshing }
}

export interface trendingResponse {
  categorie: string
  pageSize: string
  total: number
  results: TUnPost[]
}
